function rememberedId(t?:string){return String(t||"").startsWith("libraryv91:")?String(t).slice(11):""}
function score(e:V91Entry,q:string,topic?:string){let s=rememberedId(topic)===e.id?12:0;const qt=new Set(toks(q));for(const raw of [e.title,...e.aliases]){const a=norm(raw);if(!a)continue;if(q===a)s+=50;else if(a.length>=3&&q.includes(a))s+=22;const at=toks(a);let m=0;for(const t of at)if(qt.has(t)){m++;s+=t.length>=6?4:2.3}if(at.length>=2&&m===at.length)s+=8}return s}
function render(e:V91Entry,q:string){const problem=/marche pas|fonctionne pas|erreur|probleme|problème|bloque|bloqué|bug|diagnostic|incoherent|incohérent/.test(q);const how=/comment|utiliser|configurer|mettre en place|faire pour|en pratique|a quoi ca sert|à quoi ça sert/.test(q);const deep=/detail|détail|technique|expert|precis|précis|approfond|complet|complexe|pourquoi|difference|différence|compare/.test(q);let text=`## ${e.title.toUpperCase()}\n${e.definition}.`;if(deep||q.length>62)text+=`\n\n## À COMPRENDRE\n${e.deep}`;if(how||deep)text+=`\n\n## EN PRATIQUE\n${e.practice}`;if(problem)text+=`\n\n## POUR DÉPANNER\nCommence par identifier l’état attendu, le symptôme exact et ce qui a changé juste avant le problème. ${e.practice}`;if(!deep&&!how&&!problem)text+=`\n\n**À retenir :** ${e.practice}`;return text}
export function answerAwenaGrandLibraryV91(question:string,context:AwenaRuntimeContext,rememberedTopic?:string):AwenaReply|null{const q=norm(question);if(!q)return null;const rid=rememberedId(rememberedTopic);const follow=/^(?:plus de details|plus de détails|approfondis|explique davantage|pourquoi|comment|et en pratique|ca ne marche pas|ça ne marche pas|diagnostic|compare|difference|différence)$/i.test(String(question||"").trim());if(follow&&rid){const e=ENTRIES.find(x=>x.id===rid);if(e)return{text:render(e,`${q} detail`),knowledgeTopic:`libraryv91:${e.id}`,modeId:context.mode||null}}let best:{entry:V91Entry;score:number}|null=null;for(const e of ENTRIES){const s=score(e,q,rememberedTopic);if(!best||s>best.score)best={entry:e,score:s}}if(!best||best.score<14)return null;return{text:render(best.entry,q),knowledgeTopic:`libraryv91:${best.entry.id}`,modeId:context.mode||null}}
export function awenaGrandLibraryV91Count(){return ENTRIES.length}
export function awenaGrandLibraryV91AliasCount(){return ENTRIES.reduce((s,e)=>s+e.aliases.length,0)}
export function awenaGrandLibraryV91DomainCount(){return new Set(ENTRIES.map(e=>e.domain)).size}
